import java.nio.ByteBuffer;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
import org.lwjgl.glfw.GLFW;
import org.lwjgl.opengl.*;
import com.iridium126.createmanaindustry.client.particles.engine.hardware.HardwareNative;

/** Matched real contiguous read-pool geometry; never labels it a physics/FPS replay. */
public final class R7SequenceGpu extends ModelPopulationGpuValidation {
    record PathMode(String name,int backend,int period){}
    static final PathMode[] PATHS={new PathMode("cuda-control",0,1),new PathMode("tensor-control",4,1),new PathMode("tensor",3,1),new PathMode("rt-aabb-build",1,1),new PathMode("rt-aabb-4",1,4),new PathMode("rt-aabb-8",1,8),new PathMode("rt-triangle-build",2,1),new PathMode("rt-triangle-4",2,4),new PathMode("rt-triangle-8",2,8)};
    static ByteBuffer actualFile(Path root,JsonObject frame,String key,int bytes)throws Exception{byte[] data=Files.readAllBytes(root.resolve(frame.get(key).getAsString()));check(data.length==bytes&&HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(data)).equals(frame.get(key+"_sha256").getAsString()),"actual request payload");return ByteBuffer.wrap(data).order(java.nio.ByteOrder.LITTLE_ENDIAN);}
    static int[][] actualReference(float[] points,float[] requests,int[] owners){int[][] result=new int[owners.length][];for(int i=0;i<owners.length;i++){int[] found=new int[points.length/4];int count=0;for(int j=0;j<found.length;j++){if(j==owners[i])continue;float x=requests[i*4]-points[j*4],y=requests[i*4+1]-points[j*4+1],z=requests[i*4+2]-points[j*4+2],r=requests[i*4+3];if((x*x+y*y)+z*z<=r*r)found[count++]=j;}result[i]=Arrays.copyOf(found,count);}return result;}
    static void uploadActual(R7HardwareGpu.Query query,float[] requests,int[] owners){if(requests!=null){GL15.glBindBuffer(GL43.GL_SHADER_STORAGE_BUFFER,query.requests);GL15.glBufferSubData(GL43.GL_SHADER_STORAGE_BUFFER,0,requests);GL15.glBindBuffer(GL43.GL_SHADER_STORAGE_BUFFER,query.owners);GL15.glBufferSubData(GL43.GL_SHADER_STORAGE_BUFFER,0,owners);}}
    public static void main(String[] args)throws Exception{
        Path out=Path.of(System.getProperty("cmi.benchmark.output")),inputs=Path.of(System.getProperty("cmi.r7.inputs"));Files.createDirectories(out);check(!Files.exists(out.resolve("samples.csv")),"fresh run");JsonObject description=JsonParser.parseString(Files.readString(inputs.resolve("inputs.json"))).getAsJsonObject();check(description.get("periodic_rebuild_eligible").getAsBoolean(),"verified contiguous fixed topology required");
        R7HardwareGpu.out=out;R7HardwareGpu.source=out.resolve("source");Files.createDirectory(R7HardwareGpu.source);for(String name:List.of("Query.h","grid.cu","rt.cu","rt-triangle.cu","tensor.cu"))Files.copy(Path.of("native/offload",name),R7HardwareGpu.source.resolve(name));R7HardwareGpu.deps=JsonParser.parseString(Files.readString(Path.of(".gradle/neighbor-rt/dependencies.json"))).getAsJsonObject();
        check(GLFW.glfwInit(),"GLFW");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MAJOR,4);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MINOR,6);long window=GLFW.glfwCreateWindow(32,32,"R7 contiguous geometry",0,0);check(window!=0,"GL context");GLFW.glfwMakeContextCurrent(window);GL.createCapabilities();HardwareNative.load(Path.of(".gradle/hardware-offload/build"));
        int samples=Integer.getInteger("cmi.r7.samples",64),queries=Integer.getInteger("cmi.r7.queries",128);var metadata=new LinkedHashMap<String,Object>();metadata.put("passed",false);metadata.put("scope","fixed-radius=1 read-pool geometric queries, not actual local recovery/radii, full update chain, graphics competition or FPS; first stable identities queried, all members indexed");metadata.put("inputs",description);metadata.put("fixture_upload","excluded equally; uploaded before each query's timers; CPU oracle precomputed once outside all timed loops");metadata.put("samples",samples);metadata.put("process_id",ProcessHandle.current().pid());metadata.put("gpu",GL11.glGetString(GL11.GL_RENDERER));metadata.put("sdk",R7HardwareGpu.deps);
        try(var raw=Files.newBufferedWriter(out.resolve("samples.csv"))){
            raw.write("comparison,pair,side,frame,path,gpu_ms,completed_wall_ms,prepare_ms,bvh_ms,count_ms,scan_ms,write_ms\n");var frames=description.getAsJsonArray("frames");float[][] points=new float[frames.size()][];int[][][] expected=new int[frames.size()][][];int n=0,q=0,capacity=1;boolean actual=description.has("actual_requests")&&description.get("actual_requests").getAsBoolean();float[][] requests=new float[frames.size()][];int[][] owners=new int[frames.size()][];if(actual)metadata.put("scope",description.get("scope").getAsString());
            for(int f=0;f<frames.size();f++){var frame=frames.get(f).getAsJsonObject();points[f]=R6NativeReplayGpu.points(inputs,frame);if(f==0){n=points[f].length/4;q=actual?description.get("queries").getAsInt():Math.min(n,queries);}check(points[f].length==n*4,"fixed count");if(f>0){var previous=frames.get(f-1).getAsJsonObject();check(frame.get("scene_frame").getAsLong()==previous.get("scene_frame").getAsLong()+1&&frame.get("input_generation").getAsLong()==previous.get("input_generation").getAsLong()+1,"no gaps");for(int i=3;i<points[f].length;i+=4)check(Float.floatToRawIntBits(points[f][i])==Float.floatToRawIntBits(points[0][i]),"stable topology");}if(actual){requests[f]=new float[q*4];owners[f]=new int[q];actualFile(inputs,frame,"requests",q*16).asFloatBuffer().get(requests[f]);actualFile(inputs,frame,"owners",q*4).asIntBuffer().get(owners[f]);for(int id:owners[f])check(id>=0&&id<n,"actual query owner");}expected[f]=actual?actualReference(points[f],requests[f],owners[f]):NeighborQueryGpuValidation.reference(points[f],q,1);int total=0;for(int[] row:expected[f])total=Math.addExact(total,row.length);capacity=Math.max(capacity,total);}
            metadata.put("queries_per_frame",q);metadata.put("points_per_frame",n);metadata.put("output_capacity",capacity);
            try(var query=new R7HardwareGpu.Query(points[0],q,capacity,requests[0],owners[0],actual?description.get("max_radius").getAsFloat():0)){
                for(var path:PATHS){for(int f=0;f<frames.size();f++){query.putPoints(points[f]);uploadActual(query,requests[f],owners[f]);query.expected=expected[f];query.verify(path.backend,f%path.period!=0);}System.out.println("R7 sequence verified "+path.name);}
                var comparisons=new ArrayList<PathMode[]>();for(var path:PATHS)comparisons.add(new PathMode[]{path,path});for(int i=1;i<PATHS.length;i++)comparisons.add(new PathMode[]{PATHS[i==2?1:0],PATHS[i]});
                for(var comparison:comparisons){String label=(comparison[0]==comparison[1]?"AA_":"AB_")+comparison[0].name+"__"+comparison[1].name;
                    for(int pair=-4;pair<samples;pair++)for(int turn=0;turn<2;turn++){int side=(pair+turn)&1;var path=comparison[side];for(int f=0;f<points.length;f++){query.putPoints(points[f]);uploadActual(query,requests[f],owners[f]);double[] timing=query.run(path.backend,f%path.period!=0);if(pair>=0){raw.write(label+","+pair+","+side+","+f+","+path.name);for(double time:timing)raw.write(","+time);raw.write("\n");}}}raw.flush();System.out.println("R7 measured "+label);
                }
            }metadata.put("passed",true);
        }finally{metadata.put("checks",checks+R7HardwareGpu.checks);metadata.put("initialization_and_correctness",R7HardwareGpu.cases);Files.writeString(out.resolve("metadata.json"),new GsonBuilder().setPrettyPrinting().create().toJson(metadata)+"\n");GLFW.glfwDestroyWindow(window);GLFW.glfwTerminate();}
    }
}
